INSERT OR IGNORE INTO blog_regions (id, name, sort_order) VALUES ('caribe', 'Caribe', 6);
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('66cfe191-2476-4697-b9d5-4f2dd63e6c8c', 'punta-cana-praias-e-passeios', 'draft', 'caribe', 'Punta Cana em 5 dias: praias, Saona e Hoyo Azul', 'praias, Saona e Hoyo Azul', 'Roteiro de Punta Cana em 5 dias, com dois dias de praia, Ilha Saona, Hoyo Azul, e-Ticket passo a passo e o guia em PDF para baixar de graça.', 'Dois dias de praia, um na Saona, um no Hoyo Azul e um livre, com e-Ticket e vacina explicados e o guia completo para baixar e levar no celular.', 'Punta Cana', NULL, '/assets/blog/punta-cana-5-dias.jpg', '/assets/blog/punta-cana-5-dias-m.jpg', 'Praia de areia clara com coqueiros altos inclinados sobre o mar turquesa, sob um céu azul com nuvens', 0, '[{"t":"pdf","href":"/guias/punta-cana-praias-e-passeios.pdf","note":"PDF de 15 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Em Punta Cana, não fique só no resort. Este roteiro de **5 dias** reúne dois dias de praia em Bávaro, um dia na Ilha Saona, um no Hoyo Azul, em Cap Cana, e um dia livre."},{"t":"tip","items":["**Preencha o e-Ticket** no site oficial antes de ir ao aeroporto. É obrigatório e gratuito: não pague por ele.","**Veja se precisa da vacina de febre amarela.** Quem sai do ES, de MG, do RJ ou de SP precisa do certificado (CIVP). Os detalhes estão no fim da página.","**Reserve a Saona e o Scape Park antes** e confira os horários na véspera, nos sites listados no fim da página."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Bávaro","label":"Dias 1 e 2"},{"t":"p","text":"Praia para descansar da viagem e um passeio pela orla, com artesanato local."},{"t":"img","src":"/assets/blog/punta-cana-bavaro.jpg","alt":"Palmeiras e guarda-sóis de palha numa praia de areia batida, sob um céu de nuvens escuras e um brilho laranja no horizonte","caption":"Palmeiras e guarda-sóis de palha numa praia ao entardecer.","credit":"Foto: Flickr / Pexels","w":1000,"h":562},{"t":"ul","items":["**Dia 1, chegada e praia:** deixe as malas no hotel e aproveite o fim do dia na areia. Sem programação: o dia 3 começa cedo.","**Dia 2, manhã, caminhada pela orla de Bávaro:** a faixa de areia é longa e passa em frente a vários hotéis. Vá cedo, antes do sol mais forte.","**Dia 2, tarde, Bibijagua e Los Corales:** barracas de artesanato local e bares à beira-mar. Bom para comprar lembranças e ver o pôr do sol."]},{"t":"img","src":"/assets/blog/punta-cana-orla-aerea.jpg","alt":"Vista aérea de uma faixa de praia com areia clara, mar turquesa de um lado e hotéis de telhado alaranjado entre árvores do outro","caption":"Uma faixa de praia com hotéis, vista do alto.","credit":"Foto: Vitalii Rabinovych / Pexels","w":975,"h":731},{"t":"tip","items":["**Como chegar:** do aeroporto de Punta Cana (PUJ) até Bávaro são cerca de 30 minutos de carro.","**Sol:** é muito forte, mesmo com tempo nublado. Protetor solar, chapéu e água o dia todo.","**Água:** a da torneira não é própria para beber. Use água engarrafada.","**Gorjeta:** a conta do restaurante já vem com 10% de serviço. O site oficial de turismo sugere deixar mais 10% para o garçom.","**Estimativa da Rota Certa, não é dado oficial:** esforço baixo, com praia e caminhada na areia. As dicas de horário também são recomendações da Rota Certa."],"title":"Para planejar os dias 1 e 2"},{"t":"passeio","busca":"Bávaro Punta Cana","title":"Passeios em Bávaro e Punta Cana"},{"t":"h","text":"Ilha Saona","label":"Dia 3"},{"t":"p","text":"De barco até a ilha famosa pelas piscinas naturais, num dia inteiro de passeio."},{"t":"img","src":"/assets/blog/punta-cana-catamara.jpg","alt":"Catamarã de velas recolhidas, ao longe, num mar de águas rasas em tons de turquesa e céu claro","caption":"Um catamarã em águas turquesa. Foto ilustrativa, sem local confirmado.","credit":"Foto: Leonardo Rossatti / Pexels","w":1000,"h":667},{"t":"ul","items":["**Cedo, saída do hotel:** confirme na véspera o horário em que a van passa no hotel. De Bávaro até o píer a viagem é longa: tome café antes.","**Manhã, travessia até a Saona:** de lancha ou catamarã, conforme o passeio. Na ilha, praia de areia branca e coqueiros.","**Tarde, piscina natural de Palmilla:** um banco de areia no meio do mar, com água rasa e azul-turquesa, onde dá para ver estrelas-do-mar no fundo. Se quiser, leve snorkel para mergulhar."]},{"t":"tip","items":["**Como chegar:** a maioria dos passeios sai de Bayahibe, de lancha ou catamarã.","**Pergunte o que está incluído:** antes de pagar, confirme com a agência se as taxas, o transporte do hotel e o almoço estão no preço. O valor varia por agência.","**Leve:** protetor solar, chapéu, toalha e dinheiro trocado.","**Dica da Rota Certa:** não tire as estrelas-do-mar da água. E compre de agência com avaliações: desconfie de preço muito abaixo dos outros.","**Estimativa da Rota Certa, não é dado oficial:** dia inteiro, saindo cedo do hotel. Esforço baixo: barco e praia."],"title":"Para planejar o Dia 3"},{"t":"passeio","busca":"Ilha Saona","title":"Passeios à Ilha Saona"},{"t":"h","text":"Hoyo Azul e dia livre","label":"Dias 4 e 5"},{"t":"p","text":"O cenote azul-turquesa do Scape Park, em Cap Cana, e um último dia sem pressa."},{"t":"img","src":"/assets/blog/punta-cana-costa.jpg","alt":"Ondas de espuma branca batendo contra uma costa de pedras, num mar verde-azulado visto do alto","caption":"O mar batendo nas pedras do litoral. Foto ilustrativa, sem local confirmado.","credit":"Foto: Girl of Waves / Pexels","w":975,"h":650},{"t":"ul","items":["**Dia 4, manhã, Hoyo Azul:** chegue na abertura, às 9h, para pegar o cenote mais vazio. Compre o passe no site oficial do Scape Park.","**Dia 4, tarde, praia Juanillo:** águas calmas e azul-turquesa em Cap Cana, perto do Scape Park. Fim de tarde sem pressa.","**Dia 5, livre, Macao ou Cabeza de Toro:** Macao é mais natural e tem surfe. Cabeza de Toro é boa para famílias. Ou fique no hotel antes do voo."]},{"t":"tip","items":["**Horário:** o Scape Park abre todos os dias, das 9h às 17h, com atrações até 16h30. Algumas atrações têm horário limitado: veja o dia escolhido no site oficial e chegue cedo.","**Ingresso:** passes do Scape Park que incluem o Hoyo Azul. Os preços estão no site oficial.","**Leve:** roupa de banho, toalha e calçado que possa molhar.","**Na volta:** preencha o e-Ticket de saída antes de ir ao aeroporto. Ele também é obrigatório.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 30 minutos de carro de Bávaro ao Scape Park."],"title":"Para planejar os dias 4 e 5"},{"t":"passeio","busca":"Scape Park Hoyo Azul","title":"Passeios no Scape Park e no Hoyo Azul"},{"t":"h","text":"Chegada, dinheiro e tomada","label":"Na prática"},{"t":"p","text":"O aeroporto de Punta Cana (PUJ) fica a cerca de 30 minutos de Bávaro."},{"t":"ul","items":["**Do aeroporto:** táxis autorizados (Siutratural, Berón Taxi e Asotatupal), Uber, transfer de agências, que ficam no fim da alfândega, e locadoras de carro. Combine o preço do táxi antes de entrar.","**Dinheiro:** a moeda é o peso dominicano (RD$). Dólar e euro são trocados em bancos e casas de câmbio autorizadas. Leve cartão de crédito.","**Taxa de saída:** US$ 20 (cerca de R$ 101, pela PTAX de venda de 14/10/2026: US$ 1 = R$ 5,04), já incluída na passagem.","**Tomada e voltagem:** a República Dominicana usa 110 V e tomada americana, de pinos chatos. Plugue brasileiro não encaixa: leve adaptador e confira se o aparelho é bivolt."]},{"t":"carro","title":"Vai alugar um carro em Punta Cana?","text":"Há locadoras no aeroporto. Compare opções de aluguel de carro de parceiros."},{"t":"h","text":"e-Ticket, documentos e vacina","label":"Antes de ir"},{"t":"p","text":"O e-Ticket é um formulário só, grátis, para entrar e para sair do país. Ele substitui os antigos cartões de embarque, de alfândega e de saúde."},{"t":"tip","items":["**Use só o site oficial:** eticket.migracion.gob.do. O serviço não tem custo.","**Preencha antes do balcão da companhia aérea:** a empresa pode pedir. Não existe mais o prazo de 72 horas antes da viagem.","**Família num formulário só:** informe os acompanhantes no início. Acima de 7 pessoas, faça outro formulário.","**Confira o número do passaporte:** a Migração verifica o formulário por ele.","**Guarde o QR code,** impresso ou no celular. Ele é pedido na entrada do país.","**Errou?** Dá para editar até um dia antes do voo. Se não der, faça outro: vale o último.","**Ida e volta são dois QR codes:** o e-Ticket é preenchido na entrada e de novo na saída."],"title":"e-Ticket passo a passo"},{"t":"tip","items":["Quem vem do Espírito Santo, de Minas Gerais, do Rio de Janeiro ou de São Paulo precisa mostrar o Certificado Internacional de Vacinação (CIVP), com a vacina tomada pelo menos 10 dias antes da chegada."],"title":"Febre amarela: vale para 4 estados"},{"t":"ul","items":["**Sem visto para turismo:** brasileiro não precisa de visto para turismo de até 60 dias. Acima de 30 dias, há uma taxa na saída.","**Passaporte:** a regra geral pede 6 meses de validade. Para brasileiros em turismo, até 31/12/2026 basta o passaporte estar válido durante toda a estada.","**Passagem de volta e dinheiro:** a entrada exige passagem de ida e volta e prova de recursos para a estada.","**Orçamento:** preencha antes de reservar a hospedagem. O guia em PDF tem a tabela pronta."]},{"t":"tip","items":["Passaporte válido e e-Ticket com QR code.","CIVP, se você sair do ES, de MG, do RJ ou de SP.","Passagem de volta e reserva do hotel.","Seguro viagem e adaptador de tomada."],"title":"Checklist"},{"t":"pdf","href":"/guias/punta-cana-praias-e-passeios.pdf","note":"Leve o roteiro, o e-Ticket passo a passo e o orçamento no celular. Grátis, sem cadastro."},{"t":"tip","items":["[e-Ticket: site oficial da Migração](https://migracion.gob.do/servicio/solicitud-de-e-ticket-entrada-y-salida-de-pasajeros/) e [perguntas do MITUR](https://viajerodigital.mitur.gob.do/)","[Entrada, vacina e taxa de saída: turismo oficial](https://www.godominicanrepublic.com/travel/entry-requirements)","[Passaporte para brasileiros: Migração](https://migracion.gob.do/dgm-anuncia-prorroga-que-simplifica-ingreso-para-turistas-a-partir-de-este-01-de-diciembre/)","[Sem visto até 60 dias: Consulado no Rio](https://bra.mirex.gob.do/consular/rio-de-janeiro/no-necesitas-visa-para-visitar-republica-dominicana/)","[Praias e Hoyo Azul: Punta Cana](https://www.godominicanrepublic.com/destinations/punta-cana)","[Ilha Saona](https://www.godominicanrepublic.com/things-to-do/isla-saona)","[Scape Park](https://www.scapepark.com/)","[Aeroporto: transporte no PUJ](https://www.puntacanainternationalairport.com/en/airport-services/item/transportation)","[Água, gorjeta, moeda e sol: dicas oficiais](https://www.godominicanrepublic.com/travel/travel-tips)","[Tomadas: IEC](https://www.iec.ch/world-plugs)","[Câmbio: Banco Central](https://olinda.bcb.gov.br/olinda/servico/PTAX/versao/v1/odata/)"],"title":"Fontes oficiais, conferidas em 14/10/2026"},{"t":"p","text":"Horários, preços e regras mudam: confira nos sites acima antes de ir. Os preços dos passes do Scape Park e dos passeios à Saona variam por agência e não estão neste guia."},{"t":"p","text":"Foto de capa: Talita Kriunas / Pexels."},{"t":"whatsapp"},{"t":"contato"},{"t":"afiliado"}]', 6);
